// -O2
#include <cstdint>
#include <iostream>
#include <stdexcept>

// Throws for a price outside the band.
std::int64_t check_or_throw(std::int64_t price_ticks) {
    if (price_ticks <= 0 || price_ticks > 1000000) {
        throw std::invalid_argument("price out of band");
    }
    return price_ticks;
}

// Says the same thing with its return value.
bool in_band(std::int64_t price_ticks) {
    return price_ticks > 0 && price_ticks <= 1000000;
}

int main() {
    const int n = 100000;  // every 100th price is out of band
    int rejects = 0;
    std::int64_t total = 0;
    for (int i = 0; i < n; ++i) {
        const std::int64_t price = (i % 100 == 0) ? -1 : 19000 + i % 500;
        try {
            total += check_or_throw(price);
        } catch (const std::invalid_argument&) {
            ++rejects;
        }
    }
    std::cout << "throw: " << rejects << " rejects, total " << total << '\n';

    rejects = 0;
    total = 0;
    for (int i = 0; i < n; ++i) {
        const std::int64_t price = (i % 100 == 0) ? -1 : 19000 + i % 500;
        if (in_band(price)) {
            total += price;
        } else {
            ++rejects;
        }
    }
    std::cout << "code:  " << rejects << " rejects, total " << total << '\n';
    return 0;
}

