#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <new>
#include <string>
#include <unordered_map>

long g_bytes = 0;  // every heap allocation passes through here
void* operator new(std::size_t n) {
    g_bytes += n;
    if (void* p = std::malloc(n)) {
        return p;
    }
    throw std::bad_alloc();
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

// Both hashers multiply by a large odd constant to mix the bits of the id.
struct IdHash {  // as far as the library knows, this may throw
    std::size_t operator()(std::int64_t id) const { return id * 0x9E3779B97F4A7C15ULL; }
};

struct IdHashNoexcept {  // the same hash, with the promise
    std::size_t operator()(std::int64_t id) const noexcept { return id * 0x9E3779B97F4A7C15ULL; }
};

std::int64_t mid(std::int64_t bid, std::int64_t ask) noexcept { return (bid + ask) / 2; }
std::int64_t parse(const std::string& s) { return std::stoll(s); }

template <typename Hash>
long bytes_per_order(int n) {
    std::unordered_map<std::int64_t, std::int64_t, Hash> qty_by_id;
    qty_by_id.reserve(n);  // the buckets, allocated before we measure
    const long before = g_bytes;
    for (int i = 0; i < n; ++i) {
        qty_by_id.emplace(1000 + i, 100);  // one node per order
    }
    return (g_bytes - before) / n;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << "noexcept: mid " << noexcept(mid(1, 2)) << ", parse " << noexcept(parse("7"))
              << ", IdHash " << noexcept(IdHash{}(1)) << ", IdHashNoexcept " << noexcept(IdHashNoexcept{}(1)) << '\n';
    std::cout << "IdHash: " << bytes_per_order<IdHash>(1000) << " bytes per order\n";
    std::cout << "IdHashNoexcept: " << bytes_per_order<IdHashNoexcept>(1000) << " bytes per order\n";
    std::cout << "std::hash: " << bytes_per_order<std::hash<std::int64_t>>(1000) << " bytes per order\n";
    return 0;
}

