#include <cstdint>
#include <iostream>
#include <optional>
#include <string>
#include <vector>

enum class Reject : std::uint8_t { None, UnknownSymbol, PriceBand, MaxQty };

const char* describe(Reject r) {
    switch (r) {
        case Reject::None: return "accepted";
        case Reject::UnknownSymbol: return "unknown symbol";
        case Reject::PriceBand: return "price band";
        case Reject::MaxQty: return "max qty";
    }
    return "?";
}

std::optional<int> symbol_id(const std::string& symbol) {
    const std::vector<std::string> traded = {"AAPL", "MSFT", "NVDA"};
    for (int i = 0; i < static_cast<int>(traded.size()); ++i) {
        if (traded[i] == symbol) {
            return i;
        }
    }
    return std::nullopt;
}

[[nodiscard]] Reject check(const std::string& symbol, std::int64_t price_ticks, int qty) {
    if (!symbol_id(symbol).has_value()) return Reject::UnknownSymbol;
    if (price_ticks <= 0 || price_ticks > 1000000) return Reject::PriceBand;
    if (qty <= 0 || qty > 5000) return Reject::MaxQty;
    return Reject::None;
}

int main() {
    std::string symbol;
    std::int64_t price_ticks = 0;
    int qty = 0;
    int accepted = 0;
    while (std::cin >> symbol >> price_ticks >> qty) {
        const Reject r = check(symbol, price_ticks, qty);
        if (r == Reject::None) {
            ++accepted;
            std::cout << symbol << " (id " << symbol_id(symbol).value() << "): " << describe(r) << '\n';
        } else {
            std::cout << symbol << ": " << describe(r) << '\n';
        }
    }
    std::cout << "accepted " << accepted << ", sizeof(Reject) " << sizeof(Reject)
              << ", sizeof(std::optional<int>) " << sizeof(std::optional<int>) << '\n';
    return 0;
}

