#include <cstdint>
#include <iostream>
#include <optional>
#include <string>

enum class Breach : std::uint8_t { None, UnknownDesk, Position, Notional };

const char* describe(Breach b) {
    switch (b) {
        case Breach::None: return "ok";
        case Breach::UnknownDesk: return "unknown desk";
        case Breach::Position: return "position limit";
        case Breach::Notional: return "notional limit";
    }
    return "?";
}

std::optional<std::int64_t> position_limit(const std::string& desk) {
    if (desk == "RATES") return 1000;
    if (desk == "EQUITY") return 500;
    return std::nullopt;
}

[[nodiscard]] Breach check_trade(const std::string& desk, std::int64_t qty, std::int64_t price_ticks) {
    const std::optional<std::int64_t> limit = position_limit(desk);
    if (!limit.has_value()) return Breach::UnknownDesk;
    const std::int64_t size = qty < 0 ? -qty : qty;
    if (size > *limit) return Breach::Position;
    if (size * price_ticks > 10000000) return Breach::Notional;
    return Breach::None;
}

int main() {
    std::string desk;
    std::int64_t qty = 0;
    std::int64_t price_ticks = 0;
    int breaches = 0;
    while (std::cin >> desk >> qty >> price_ticks) {
        const Breach b = check_trade(desk, qty, price_ticks);
        if (b != Breach::None) {
            ++breaches;
        }
        std::cout << desk << ' ' << qty << ": " << describe(b) << '\n';
    }
    std::cout << "breaches " << breaches << '\n';
    return 0;
}

