#include <cstdint>
#include <iostream>
#include <string>
#include <utility>
#include <variant>

template <typename E>
struct Err {
    explicit Err(E c) : code(c) {}
    E code;
};

template <typename T, typename E>
class Result {
public:
    Result(T value) : v_(std::move(value)) {}
    Result(Err<E> err) : v_(err) {}
    bool ok() const { return v_.index() == 0; }
    const T& value() const { return std::get<0>(v_); }
    E error() const { return std::get<1>(v_).code; }

private:
    std::variant<T, Err<E>> v_;
};

enum class ParseError : std::uint8_t { NotANumber, TooLong, OutOfBand };

const char* describe(ParseError e) {
    switch (e) {
        case ParseError::NotANumber: return "not a number";
        case ParseError::TooLong: return "too long";
        case ParseError::OutOfBand: return "out of band";
    }
    return "?";
}

// "19275" -> 19275 ticks. Never throws.
Result<std::int64_t, ParseError> parse_price(const std::string& text) {
    if (text.size() > 9) return Err(ParseError::TooLong);
    std::int64_t ticks = 0;
    for (char c : text) {
        if (c < '0' || c > '9') return Err(ParseError::NotANumber);
        ticks = ticks * 10 + (c - '0');
    }
    if (ticks == 0 || ticks > 1000000) return Err(ParseError::OutOfBand);
    return ticks;
}

int main() {
    std::string token;
    std::int64_t total = 0;
    while (std::cin >> token) {
        const Result<std::int64_t, ParseError> r = parse_price(token);
        if (r.ok()) {
            total += r.value();
            std::cout << token << " -> " << r.value() << '\n';
        } else {
            std::cout << token << " -> error: " << describe(r.error()) << '\n';
        }
    }
    std::cout << "total " << total << ", sizeof(Result) " << sizeof(Result<std::int64_t, ParseError>) << '\n';
    return 0;
}

