template <typename E>
struct Err {
    explicit Err(E c) : code(c) {}
    E code;
};

template <typename T, typename E>
class Result {
public:
    Result(T value) : v_(std::move(value)) {}
    Result(Err<E> err) : v_(err) {}
    bool ok() const { return v_.index() == 0; }
    const T& value() const { return std::get<0>(v_); }
